<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import type {Dataset,Station} from '../../services/local/types'
import {fields,parseCsv,unitLabel} from '../../services/local/fields'
import {errorText,localApi} from '../../services/local/api'
import {csv} from '../../utils'
const props=defineProps<{station:Station}>(),emit=defineEmits<{imported:[data:Dataset]}>()
const file=ref<File>(),rows=ref<string[][]>([]),delimiter=ref(','),mapping=ref<Record<string,string>>({}),units=ref<Record<string,string>>({}),timeColumn=ref(''),name=ref(''),error=ref(''),busy=ref(false),result=ref<Dataset>(),fileKey=ref(0)
const headers=computed(()=>rows.value[0]??[]),valid=computed(()=>file.value&&timeColumn.value&&name.value.trim()&&fields.every(f=>mapping.value[f.field])&&new Set([timeColumn.value,...Object.values(mapping.value).filter(Boolean)]).size===9)
let generation=0
watch(()=>props.station.id,()=>{generation++;file.value=undefined;rows.value=[];mapping.value={};result.value=undefined;fileKey.value++;error.value=''})
async function parse(){const run=++generation;error.value='';rows.value=[];mapping.value={};result.value=undefined;if(!file.value)return
 try{if(file.value.size>20*1024*1024)throw new Error('首期前端预览支持 20 MB 以内 CSV，请先拆分文件。');const text=await file.value.text();if(run!==generation)return;rows.value=parseCsv(text,delimiter.value);timeColumn.value=headers.value.find(h=>['时间','timestamp','datetime'].includes(h))??'';name.value=file.value.name.replace(/\.csv$/i,'');for(const f of fields){mapping.value[f.field]=headers.value.includes(f.field)?f.field:'';units.value[f.field]=f.unit}}
 catch(e){if(run===generation)error.value=errorText(e)}
}
function choose(event:globalThis.Event){file.value=(event.target as HTMLInputElement).files?.[0];void parse()}
async function submit(){if(!valid.value||busy.value||!file.value)return;busy.value=true;error.value='';const stationId=props.station.id
 try{const data=await localApi.importDataset(file.value,{name:name.value.trim(),stationId,timezone:props.station.timezone,encoding:'utf-8-sig',delimiter:delimiter.value,timeColumn:timeColumn.value,columnMapping:Object.fromEntries(fields.map(f=>[mapping.value[f.field],f.field])),sourceUnits:{...units.value}});if(props.station.id!==stationId)return;result.value=data;emit('imported',data)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function template(){csv([['时间',...fields.map(f=>f.field)],['2026-11-08T00:00:00+08:00',...fields.map(()=> '')]],'本站数据模板-请填写实际数据.csv')}
</script>
<template><form class="local-import" @submit.prevent="submit"><fieldset :disabled="busy"><legend>导入 {{station.name}} 的运行数据</legend><p class="muted">CSV 需使用 UTF-8 编码。确认侧别、瞬时量与单位；转换和质量校验由本机后端执行。</p><div class="local-form-grid"><label>运行数据 CSV<input :key="fileKey" type="file" accept=".csv,text/csv" required @change="choose" /></label><label>分隔符<select v-model="delimiter" @change="parse"><option value=",">逗号</option><option value=";">分号</option></select></label></div><button type="button" class="text-button" @click="template">下载空白字段模板</button><template v-if="rows.length"><div class="local-form-grid"><label>数据集名称<input v-model="name" maxlength="80" required /></label><label>时间列<select v-model="timeColumn" required><option value="">请选择</option><option v-for="h in headers" :key="h">{{h}}</option></select></label></div><p>数据时区：{{station.timezone}} · 预览 {{rows.length-1}} 行 · 不以预览代替后端校验</p><div class="table-wrap"><table><thead><tr><th>模型必需测点</th><th>CSV 原始列</th><th>原始单位（请确认）</th></tr></thead><tbody><tr v-for="f in fields" :key="f.field"><td>{{f.label}}</td><td><select v-model="mapping[f.field]" :aria-label="f.label+'对应列'" required><option value="">请选择</option><option v-for="h in headers" :key="h">{{h}}</option></select></td><td><select v-model="units[f.field]" :aria-label="f.label+'原始单位'"><template v-if="f.unit==='L/h'"><option value="L/h">L/h</option><option value="m3/h">m³/h</option></template><template v-else-if="f.unit==='kW'"><option value="kW">kW</option><option value="W">W</option><option value="MW">MW</option></template><option v-else :value="f.unit">{{unitLabel(f.unit)}}</option></select></td></tr></tbody></table></div><p v-if="!valid" class="muted">请完整选择时间和八个测点，每个原始列只能使用一次。</p><details><summary>查看前 5 行原始数据</summary><div class="table-wrap"><table><thead><tr><th v-for="h in headers" :key="h">{{h}}</th></tr></thead><tbody><tr v-for="(r,i) in rows.slice(1,6)" :key="i"><td v-for="(v,j) in r" :key="j">{{v||'空值'}}</td></tr></tbody></table></div></details></template><button class="primary mt" :disabled="!valid||busy">{{busy?'导入并校验中…':'导入并校验本站数据'}}</button></fieldset><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="result" role="status"><p>{{result.status==='ready'?'数据已保存，可用于检测。':'数据已保存，但存在阻断问题，暂不能检测。'}}</p><ul><li v-for="(issue,i) in result.issues" :key="i">{{issue.blocking?'阻断':'提示'}}：{{issue.message}}（{{issue.count}} 条）</li></ul></div></form></template>
